class n extends HTMLElement{connectedCallback(){const t=this.querySelector(".segmented-control__pill"),l=()=>{const e=this.querySelector("input[type='radio']:checked"),s=this.querySelector(`label[for="${e.id}"]`);t.style.width=`${s.offsetWidth}px`,t.style.transform=`translateX(${s.offsetLeft}px)`};this.classList.add("js-pill-active"),this.querySelectorAll("input[type='radio']").forEach(e=>{e.addEventListener("change",l)}),l()}}customElements.get("segmented-control")||customElements.define("segmented-control",n);
